<fieldset data-stock-item class="stock-proposal-item"><legend>Product item</legend>
<?php
// Units (D-16, ADR-022): the quantity is entered in a unit of the product and stored in base units. Product options carry
// their units; for returns the unit list comes from the original movement's product (loaded by inventory-operations.js).
$unitSets=$unitSets??[];$selectedUnit=$itemState->value('unit_code','');$firstUnits=null;
foreach($products as $product){ if($firstUnits===null || (string)$product->id()===$itemState->value('product_id','')){ $firstUnits=[$product,$unitSets[$product->id()]??\App\Support\UnitSet::forProduct($product)]; } }
?>
<label class="field" data-stock-field="regular"><span class="field-label">Product</span><select data-stock-input="product_id" name="<?= $escape($prefix) ?>product_id<?= $prefix!==''?']':'' ?>"><?php foreach($products as $product): $set=$unitSets[$product->id()]??\App\Support\UnitSet::forProduct($product); ?><option value="<?= $product->id() ?>" data-base-unit="<?= $escape($set->baseCode()) ?>" data-units="<?= $escape((string)json_encode($set->describe($product),JSON_UNESCAPED_UNICODE)) ?>" <?= $itemState->selected('product_id',$product->id(),false) ?>><?= $escape($product->sku().' — '.$product->name()) ?></option><?php endforeach; ?></select></label>
<label class="field" data-stock-field="adjustment"><span class="field-label">Stock baseline at count</span><input data-stock-input="baseline" name="<?= $escape($prefix) ?>baseline<?= $prefix!==''?']':'' ?>" type="number" min="0" readonly value="<?= $escape($itemState->value('baseline','')) ?>"></label>
<label class="field" data-stock-field="adjustment"><span class="field-label">Lot</span><select data-stock-input="lot_id" data-stock-optional name="<?= $escape($prefix) ?>lot_id<?= $prefix!==''?']':'' ?>" data-selected="<?= $escape($itemState->value('lot_id','')) ?>"><option value="">Whole product (all lots)</option><?php if($itemState->value('lot_id','')==='new'): ?><option value="new" selected>New lot found at the count</option><?php elseif($itemState->value('lot_id','')!==''): ?><option value="<?= $escape($itemState->value('lot_id','')) ?>" selected>Lot #<?= $escape($itemState->value('lot_id','')) ?></option><?php endif; ?></select></label>
<div data-stock-new-lot <?= $itemState->value('lot_id','')==='new'?'':'hidden' ?>><label class="field"><span class="field-label">New lot code</span><input data-stock-input="lot_code" data-stock-optional name="<?= $escape($prefix) ?>lot_code<?= $prefix!==''?']':'' ?>" maxlength="60" value="<?= $escape($itemState->value('lot_code','')) ?>"></label><label class="field"><span class="field-label">Expiry date (required when the product tracks expiry)</span><input data-stock-input="expiry_date" data-stock-optional type="date" name="<?= $escape($prefix) ?>expiry_date<?= $prefix!==''?']':'' ?>" value="<?= $escape($itemState->value('expiry_date','')) ?>"></label></div>
<label class="field" data-stock-field="return"><span class="field-label">Original receipt/issue ledger ID</span><input data-stock-input="source_ledger_id" name="<?= $escape($prefix) ?>source_ledger_id<?= $prefix!==''?']':'' ?>" inputmode="numeric" value="<?= $escape($itemState->value('source_ledger_id','')) ?>"></label>
<output data-stock-source-summary></output>
<label class="field"><span class="field-label" data-stock-quantity-label>Counted Quantity</span><input data-stock-input="quantity" name="<?= $escape($prefix) ?>quantity<?= $prefix!==''?']':'' ?>" type="number" min="0" max="4294967295" required value="<?= $escape($itemState->value('quantity','')) ?>"></label>
<label class="field"><span class="field-label">Unit</span><select data-stock-input="unit_code" data-stock-unit name="<?= $escape($prefix) ?>unit_code<?= $prefix!==''?']':'' ?>"><?php if($firstUnits!==null): foreach($firstUnits[1]->active() as $unit): ?><option value="<?= $escape($unit->code()) ?>" data-factor="<?= $unit->factor() ?>"<?= ($selectedUnit!==''?strcasecmp($selectedUnit,$unit->code())===0:$unit->isBase())?' selected':'' ?>><?= $escape($unit->code().($unit->isBase()?'':' ('.$unit->factor().' '.$firstUnits[1]->baseCode().')')) ?></option><?php endforeach; endif; ?></select></label>
<p class="field-hint" data-stock-base-hint aria-live="polite"></p>
<label class="field" data-stock-field="customer"><span><input type="checkbox" data-stock-input="fit_for_stock" name="<?= $escape($prefix) ?>fit_for_stock<?= $prefix!==''?']':'' ?>" value="1" <?= $itemState->value('fit_for_stock','')==='1'?'checked':'' ?>> Returned goods are fit to re-enter stock.</span></label>
<button type="button" class="button button-quiet" data-stock-remove <?= $prefix===''?'disabled':'' ?>>Remove item</button>
</fieldset>
